        try:
            import json
            with open(user_cat_file, 'r') as f:
                return json.load(f)
        except Exception:
            pass

    # 2. Try factory defaults
    if os.path.exists(default_cat_file):
        try:
            import json
            with open(default_cat_file, 'r') as f:
                return json.load(f)
        except Exception:
            pass

    # 3. Ultimate fallback
    return {
        "Housing": {"Rent": []}, 
        "Income": {"Salary": []}, 
        "Miscellaneous": {"Uncategorized": []}
    }

