class ParserFactory:
    """
    Factory to manage different bank parsers.
    Add new bank modules here.
    """
    _parsers: Dict[str, Type[BaseBankParser]] = {
        "sanpaolo": SanPaoloParser,
        "csv": CSVParser,
        "unicredit": UnicreditParser,
        "revolut": RevolutParser,
    }

    @classmethod
    def get_parser(cls, bank_name: str) -> BaseBankParser:
        parser_class = cls._parsers.get(bank_name.lower())
        if not parser_class:
            raise ValueError(f"No parser implemented for bank: {bank_name}")
        return parser_class()

