                        bank_display_name = template["name"]
                    else:
                        # Fallback to generic CSV if nothing matches
                        parser = ParserFactory.get_parser("csv")
                        parsed_transactions = parser.parse(file_path)
                        bank_display_name = parser.bank_name

                if dry_run:
