                                        parsed_date = datetime.datetime.strptime(v, "%Y-%m-%d").date()
                                    elif isinstance(v, datetime.date): 
                                        parsed_date = v
                                 except: pass

                        parsed_net = 0.0

                        # 1. Priority: Explicit DB Mapping
                        if "net_income" in raw_result:
