                                        elif isinstance(v, str): 
                                            clean_val = v.replace('.','').replace(',','.')
                                            parsed_net = float(clean_val)
                                     except: pass

                        salary_entry = Salary(
                            date=parsed_date,
                            net_income=parsed_net,
                            filename=file.filename,
                            raw_data=raw_result
                        )
                        db.add(salary_entry)
                        db.commit()
                        results.append({"filename": file.filename, "status": "success", "parser_used": template["name"]})

                else:
                    logger.warning("No valid parser template found for salary upload.")
                    results.append({"filename": file.filename, "status": "error", "message": "No valid parser template found. Please select a template."})

        except Exception as e:
            if not dry_run: db.rollback()
