async def _persist_salary_relational_data(db: Session, salary_id: int, raw_result: dict):
    """
    Smart mapper from generic parser JSON to relational schema.
    """
    # 1. Salary Items (Competence/Items)
    # Heuristic: look for lists with 'COD' or 'Description'
    for key, val in raw_result.items():
        if isinstance(val, list) and len(val) > 0:
            sample = val[0]
            if isinstance(sample, dict) and (any(k in sample for k in ['COD', 'Code', 'Descrizione', 'Description'])):
                for row in val:
                    # Map row to SalaryItem
                    item_data = {
                        "salary_id": salary_id,
                        "code": str(row.get('COD') or row.get('Code') or ""),
                        "description": str(row.get('Descrizione') or row.get('Description') or ""),
                        "quantity": float(row.get('ORE/GG') or row.get('Qty') or row.get('quantity') or 0.0),
                        "base_data": float(row.get('Base') or row.get('base_data') or 0.0),
                        "earnings": float(row.get('Competenze') or row.get('earnings') or 0.0),
                        "deductions": float(row.get('Trattenute') or row.get('deductions') or 0.0),
                    }
                    if item_data["code"] or item_data["description"]:
                        item_data["type"] = "Deduction" if item_data["deductions"] != 0 else "Earning"
                        db.add(SalaryItem(**item_data))

            # 2. Attendance (In/Out)
            elif isinstance(sample, dict) and (any(k in sample for k in ['DateIn', 'TimeIn', 'Data entrata'])):
                for row in val:
                    try:
                        date_val = row.get('DateIn') or row.get('Data entrata')
                        if isinstance(date_val, str):
                            # Generic date parser in main.py? No, let's use a simple one
                            # Expected YYYY-MM-DD from DataParser
                            d = datetime.datetime.strptime(date_val, "%Y-%m-%d").date()
                        else:
                            d = datetime.date.today() # Fallback

                        db.add(Attendance(
                            salary_id=salary_id,
                            date=d,
                            entry_time=str(row.get('TimeIn') or ""),
                            exit_time=str(row.get('TimeOut') or "")
                        ))
                    except:
                        continue

            # 3. Leaves (Ferie)
            elif isinstance(sample, dict) and 'Rows' in sample and any(k in sample for k in ['Ferie', 'BancaOre']):
                for row in val:
                    row_type = row.get('Rows')
                    leave_map = {
                        "Res.A.P.": "previous_residue",
                        "Mat.Anno": "accrued",
                        "Goduto": "used",
