                            Transaction.date == t["date"],
                            Transaction.amount == t["amount"],
                            Transaction.operation == t["operation"],
                            Transaction.details == t.get("details", "")
                        ).first()

                        if not exists:
                            tx_data = {k: v for k, v in t.items() if hasattr(Transaction, k)}
                            db.add(Transaction(**tx_data))
                            count += 1
                    db.commit()
                    results.append({"filename": file.filename, "status": "success", "rows": count, "parser_used": bank_display_name})

            elif doc_type == "salary":
                # Check for explicit parser/template (Generic Pipeline)
                use_generic = False
                template = None

                logger.info(f"Processing Salary Upload. Parser Name: {parser_name}")
                if parser_name and parser_name not in ["auto", "default"]:
                    template = TemplateManager.get_by_id(parser_name)
                    logger.info(f"Template Lookup: {template is not None}")
                    if template:
                        use_generic = True

                if use_generic:
                    # Generic Parser Logic
                    raw_result = GenericPDFParser.parse(file_path, template)

                    if dry_run:
                        # Flatten for preview
                        preview_items = []
                        for k, v in raw_result.items():
                            if isinstance(v, list):
                                preview_items.append({"date": "Table", "operation": k, "amount": len(v), "details": "rows"})
                            else:
                                preview_items.append({"date": k, "operation": str(v), "amount": 0, "details": ""})

                        results.append({
                            "filename": file.filename,
                            "status": "preview",
                            "parser_used": template["name"],
                            "original_snippet": original_snippet,
                            "parsed_preview": preview_items,
                            "total_parsed": len(raw_result)
                        })
                    else:
                        # Map to Salary Schema
                        # Minimum Requirements: date, net_income
                        parsed_date = datetime.date.today()

                        # Recursive search for date and net_income in raw_result
                        def find_key_recursive(d, target_keys):
                            if not isinstance(d, dict): return None
                            for k, v in d.items():
                                if k.lower() in [tk.lower() for tk in target_keys]:
                                    return v
                                if isinstance(v, dict):
                                    res = find_key_recursive(v, target_keys)
                                    if res is not None: return res
                            return None

                        # Try to find date
                        found_date = find_key_recursive(raw_result, ["date", "data", "periodo", "month_reference", "Month"])
                        if found_date:
                            try:
                                if isinstance(found_date, str):
                                    # Try various formats
                                    for fmt in ["%Y-%m-%d", "%d/%m/%Y", "%d.%m.%Y"]:
                                        try:
                                            parsed_date = datetime.datetime.strptime(found_date, fmt).date()
                                            break
                                        except: continue
                                elif isinstance(found_date, datetime.date):
                                    parsed_date = found_date
                            except: pass

                        parsed_net = 0.0
                        found_net = find_key_recursive(raw_result, ["net_income", "netto", "netto a pagare", "Netto"])
                        if found_net:
                            try:
                                if isinstance(found_net, (int, float)): parsed_net = float(found_net)
                                elif isinstance(found_net, str):
                                    clean_val = found_net.replace('.','').replace(',','.')
                                    parsed_net = float(clean_val)
                            except: pass

                        salary_entry = Salary(
                            date=parsed_date,
                            net_income=parsed_net,
                            filename=file.filename,
                            raw_data=raw_result
                        )
                        db.add(salary_entry)
                        db.commit()
                        db.refresh(salary_entry)

                        # Persist relational details
                        await _persist_salary_relational_data(db, salary_entry.id, raw_result)

                        results.append({"filename": file.filename, "status": "success", "parser_used": template["name"]})

                else:
                    logger.warning("No valid parser template found for salary upload.")
                    results.append({"filename": file.filename, "status": "error", "message": "No valid parser template found. Please select a template."})

        except Exception as e:
            if not dry_run: db.rollback()
            logger.error(f"Error: {str(e)}")
            results.append({"filename": file.filename, "status": "error", "message": str(e)})

    return {"status": "completed", "results": results}

