    if os.path.exists(default_cat_file):
        try:
            import json
            with open(default_cat_file, 'r') as f:
                return json.load(f)
        except Exception:
            pass

    # 3. Ultimate fallback
    return {
        "Housing": {"Rent": []}, 
        "Income": {"Salary": []}, 
